import sys
import argparse

class RomanConverter:
    ROMAN_NUMERAL_MAP = (
        ('M',  1000),
        ('CM', 900),
        ('D',  500),
        ('CD', 400),
        ('C',  100),
        ('XC', 90),
        ('L',  50),
        ('XL', 40),
        ('X',  10),
        ('IX', 9),
        ('V',  5),
        ('IV', 4),
        ('I',  1)
    )

    @classmethod
    def to_roman(cls, number):
        if not (0 < number < 4000):
            raise ValueError("Input must be between 1 and 3999")
        result = []
        for roman, value in cls.ROMAN_NUMERAL_MAP:
            while number >= value:
                result.append(roman)
                number -= value
        return ''.join(result)

    @classmethod
    def from_roman(cls, roman):
        i = 0
        result = 0
        roman = roman.upper()
        for numeral, integer in cls.ROMAN_NUMERAL_MAP:
            while roman[i:i+len(numeral)] == numeral:
                result += integer
                i += len(numeral)
                if i >= len(roman):
                    break
        if cls.to_roman(result) != roman:
            raise ValueError("Invalid Roman numeral")
        return result


def main():
    parser = argparse.ArgumentParser(description='Convert integers to Roman numerals and vice versa.')
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('-i', '--integer', type=int, help='Integer to convert to Roman numeral')
    group.add_argument('-r', '--roman', type=str, help='Roman numeral to convert to integer')

    args = parser.parse_args()

    if args.integer is not None:
        try:
            print(RomanConverter.to_roman(args.integer))
        except ValueError as e:
            print(e, file=sys.stderr)
            sys.exit(1)

    if args.roman is not None:
        try:
            print(RomanConverter.from_roman(args.roman))
        except ValueError as e:
            print(e, file=sys.stderr)
            sys.exit(1)

if __name__ == '__main__':
    main()
